def report(text):
    # parse
    rows = []
    for line in text.splitlines():
        if line.strip() == "":
            continue
        parts = line.split(",")
        rows.append((parts[0].strip(), int(parts[1])))
    if len(rows) == 0:
        return "no students"
    # average
    total = 0
    for row in rows:
        total = total + row[1]
    avg = total / len(rows)
    # best
    best = rows[0]
    for row in rows:
        if row[1] > best[1]:
            best = row
    # format
    return f"{len(rows)} students, average {avg:.1f}, best {best[0]} ({best[1]})"

