def parse_scores(text):
    scores = []
    for line in text.splitlines():
        if line.strip():
            name, score = line.split(",")
            scores.append((name.strip(), int(score)))
    return scores


def average(scores):
    return sum(score for _, score in scores) / len(scores)


def best_student(scores):
    return max(scores, key=lambda pair: pair[1])


def report(text):
    scores = parse_scores(text)
    if not scores:
        return "no students"
    name, score = best_student(scores)
    return (
        f"{len(scores)} students, "
        f"average {average(scores):.1f}, "
        f"best {name} ({score})"
    )

