DISCOUNTS = {}


def discount_rule(name):
    def register(rule):
        DISCOUNTS[name] = rule
        return rule
    return register


@discount_rule("none")
def no_discount(total):
    return total


@discount_rule("half")
def half_price(total):
    return total / 2


@discount_rule("ten_off")
def ten_off(total):
    return max(total - 10, 0)


@discount_rule("fifth_off")
def fifth_off(total):
    return total * 0.8


def apply_discount(kind, total):
    try:
        rule = DISCOUNTS[kind]
    except KeyError:
        raise ValueError(f"unknown discount: {kind!r}") from None
    return rule(total)

